const firstLine = (text: string): string => text.split('\n').find(line => line.trim().length > 0)?.trim() ?? ''

// Claude Code's answer when the person says no at a permission prompt. No event names that call, so its text is
// the only sign; auto mode's denials come as `classic.PermissionDenied` with the call's id instead.
const REFUSAL = /^The user doesn't want to (?:proceed|take this action)/

// A call refused before it ran: a hook's deny, or the person's no at a permission prompt. A choice, not a fizzle.
export const isRefusal = (ran: { deny?: string; isError?: boolean; text?: string }): boolean =>
  ran.deny !== undefined || (ran.isError === true && REFUSAL.test(ran.text ?? ''))

// A tool's touch on a file, counted under the path relative to the session's folder.
export const touchFile = (list: readonly TouchedFile[], path: string, isEdit: boolean): TouchedFile[] => {
  const found = list.find(file => file.path === path) ?? { path, reads: 0, edits: 0 }
  const next = { ...found, reads: found.reads + (isEdit ? 0 : 1), edits: found.edits + (isEdit ? 1 : 0) }
  return [...list.filter(file => file.path !== path), next].slice(-200)
}

// The skill a typed `/name args` prompt invokes, when `name` is a known skill.
export const skillOfPrompt = (text: string, known: readonly string[]): string | undefined => {
  const name = /^\/([\w:.-]+)/.exec(text.trim())?.[1]
  return name !== undefined && known.includes(name) ? name : undefined
}

// Changes waiting to be saved, and the saves, one after another: each reads what the last one wrote.
let pendingChanges: ((p: Progress) => Progress)[] = []
let progressQueue: Promise<void> = Promise.resolve()

// Applies every waiting change to the lifetime progress in one store read and write. The store is shared by
// every session, so the changes apply to what the store holds now, other sessions' work included, never to this
// session's copy; this session's copy then follows the store.
async function saveProgress($: EngineInterface) {
  if (pendingChanges.length === 0) return
  const changes = pendingChanges
  pendingChanges = []
  // A store that cannot be read is never written: building on nothing would erase every session's progress.
  // This session's copy takes the changes alone until the store answers again.
  const read_ = await $.store.get(PROGRESS_KEY).then(
    value => ({ isRead: true, value: value as Partial<Progress> | undefined }),
    () => ({ isRead: false, value: undefined }),
  )
  const base = read_.isRead ? read_.value : await read($, progress)
  const next = changes.reduce((p, change) => change(p), progressOf(base))
  if (read_.isRead) {
    // A failed write keeps the changes for the next save rather than dropping the whole batch.
    const isSaved = await $.store.set(PROGRESS_KEY, next).then(() => true, () => false)
    if (!isSaved) {
      pendingChanges = [...changes, ...pendingChanges]
      return
    }
  }
  await update($, progress, () => next)
}

// Queues `change` to the lifetime progress. Changes made while a save runs wait for the next one, which takes
// them all at once, so a burst of tool calls costs one store round trip, not one each. Never rejects: a caller
// on the tool path need not wait.
function advance($: EngineInterface, change: (p: Progress) => Progress): Promise<void> {
  pendingChanges.push(change)
  progressQueue = progressQueue.then(() => saveProgress($)).catch(() => undefined)
  return progressQueue
}

async function loadProgress($: EngineInterface) {
  const stored = (await $.store.get(PROGRESS_KEY).catch(() => undefined)) as Partial<Progress> | undefined
  await update($, progress, () => progressOf(stored))
}

// How full the context gets before mana runs low, warned once each until a compact or /clear empties it again.
export const MANA_ALARMS = [80, 90] as const

// The alarm `percent` sounds after `warned` (the last alarm sounded), and the alarm to remember next. Falling
// below an alarm forgets it, so a context filled again after a compact warns again.
export const manaAlarm = (percent: number, warned: number): { alarm?: number; warned: number } => {
  const reached = MANA_ALARMS.filter(level => percent >= level).at(-1) ?? 0
  return reached > warned ? { alarm: reached, warned: reached } : { warned: Math.min(warned, reached) }
}

// The last alarm this session sounded.
let manaWarned = 0

async function refreshVitals($: EngineInterface) {
  const usage = await $.session.usage().catch(() => undefined)
  if (usage === undefined) return
  const contextPercent = usage.context.percent
  await update($, vitals, () => ({ contextPercent, usd: usage.cost?.usd }))
  if (contextPercent === undefined) return
  const { alarm, warned } = manaAlarm(contextPercent, manaWarned)
  manaWarned = warned
  if (alarm !== undefined) $.ui.toast(`🔮 Mana low: context ${alarm}% full. /compact to restore it`)
}

// The skills and MCP servers the context lists, from the free local estimate of /context.
async function refreshLoadout($: EngineInterface) {
  const usage = await $.session.usage({ breakdown: 'summary' }).catch(() => undefined)
  const breakdown = usage?.context.breakdown
  if (breakdown === undefined) return
  const skills = (breakdown.skills?.skillFrontmatter ?? []).map(skill => ({
    name: skill.name,
    source: skill.source,
    ...(skill.pluginName === undefined ? {} : { plugin: skill.pluginName }),
  }))
  const servers = new Map<string, Gear>()
  for (const tool of breakdown.mcpTools) {
    const gear = servers.get(tool.serverName) ?? { server: tool.serverName, tools: 0, isLoaded: false }
    servers.set(tool.serverName, { ...gear, tools: gear.tools + 1, isLoaded: gear.isLoaded || tool.isLoaded })
  }
  const gear = [...servers.values()].sort((a, b) => a.server.localeCompare(b.server))
  await update($, loadout, () => ({ skills, gear }))
}

const toplevel = async ($: EngineInterface) =>
  (await $.process.run(['git', 'rev-parse', '--show-toplevel']).catch(() => undefined))?.stdout.trim()

// A path with its symbolic links resolved (macOS's /tmp is /private/tmp), or as given when it cannot be.
const realOf = async ($: EngineInterface, path: string) =>
  (await $.fs.stat(path, { resolve: true }).catch(() => undefined))?.realPath ?? path

const baseName = (path: string) => path.split('/').filter(part => part.length > 0).pop() ?? path

// One folder's bag from its status: numstat run in `root` (an outpost) or the session's folder, untracked files
// read from `base`. A file git does not track yet has no numstat: its lines all count as added.
async function loadBag($: EngineInterface, status: string, root: string | undefined, base: string | undefined) {
  const numstat = await $.process.run(root === undefined ? GIT_NUMSTAT : outpostArgv.numstat(root)).catch(() => undefined)
  const items = parseBag(status, numstat?.exitCode === 0 ? numstat.stdout : '')
  let counted = 0
  return Promise.all(
    items.map(async item => {
      if (item.status !== '?' || base === undefined || counted >= COUNTED_NEW_FILES) return item
      counted += 1
      const text = await $.fs.read(`${base}/${item.path}`).catch(() => undefined)
      return text === undefined ? item : { ...item, added: text.split('\n').length - (text.endsWith('\n') ? 1 : 0) }
    }),
  )
}

// `files`: what an edit can change, the status and the bag. `all`: the graph, the remotes and the outposts too.
async function refreshMap($: EngineInterface, scope: 'files' | 'all' = 'all') {
  const isAll = scope === 'all'
  const [status, log, remoteList] = await Promise.all([
    $.process.run(GIT_STATUS).catch(() => undefined),
    isAll ? $.process.run(GIT_LOG).catch(() => undefined) : undefined,
    isAll ? $.process.run(GIT_REMOTES).catch(() => undefined) : undefined,
  ])
  if (status === undefined || status.exitCode !== 0) {
    await update($, map, current => ({ ...current, isRepo: false }))
    await update($, bag, () => [])
    await update($, outposts, () => [])
    return
  }
  const root = await toplevel($)
  if (isAll) {
    const graph = log?.exitCode === 0 ? log.stdout.split('\n').filter(line => line.length > 0) : []
    const remotes = remoteList?.exitCode === 0 ? remoteList.stdout.split('\n').filter(name => name.length > 0) : []
    await update($, map, () => ({ isRepo: true, graph, remotes, ...(root === undefined ? {} : { root }), ...parseStatus(status.stdout) }))
  } else {
    await update($, map, current => ({ ...current, isRepo: true, ...parseStatus(status.stdout) }))
  }
  const items = await loadBag($, status.stdout, undefined, root)
  await update($, bag, () => items)
  if (isAll) await listOutposts($, root, false)
}

// The worktrees as outposts. Listing them is one git run; `survey` also reads each one's branch distance, unsaved
// work and last commit (two runs each), which only the outposts view shows, so it alone asks for it.
// Without a survey an outpost keeps the figures its last one found.
async function listOutposts($: EngineInterface, root: string | undefined, survey: boolean) {
  const listed = await $.process.run(GIT_WORKTREES).catch(() => undefined)
  if (listed === undefined || listed.exitCode !== 0) return void (await update($, outposts, () => []))
  const entries = parseWorktrees(listed.stdout)
  // One outpost is the repository alone: nothing to show.
  if (entries.length < 2) return void (await update($, outposts, () => []))
  const here = root === undefined ? undefined : await realOf($, root)
  const previous = await read($, outposts)
  const list = await Promise.all(
    entries.map(async (entry, index): Promise<Outpost> => {
      const old = previous.find(one => one.path === entry.path)
      const realPath = await realOf($, entry.path)
      const known = { ahead: old?.ahead ?? 0, behind: old?.behind ?? 0, dirty: old?.dirty ?? 0, age: old?.age ?? '' }
      const outpost = { ...entry, realPath, isHere: realPath === here, ...known }
      if (!survey || entry.isPrunable || index >= SURVEYED_OUTPOSTS) return outpost
      const [status, age] = await Promise.all([
        $.process.run(outpostArgv.status(entry.path)).catch(() => undefined),
        $.process.run(outpostArgv.age(entry.path)).catch(() => undefined),
      ])
      const { ahead, behind, dirty } = status?.exitCode === 0 ? parseStatus(status.stdout) : known
      return { ...outpost, ahead, behind, dirty, age: age?.exitCode === 0 ? shortAge(age.stdout.trim()) : known.age }
    }),
  )
  await update($, outposts, () => list)
}

const surveyOutposts = async ($: EngineInterface) => listOutposts($, await toplevel($), true)

// Opens an outpost's bag: the session's own folder shows the usual bag, another worktree its own.
// Either way back leads to the outposts list it was opened from.
async function openOutpost($: EngineInterface, path: string) {
  const outpost = (await read($, outposts)).find(one => one.path === path)
  if (outpost === undefined || outpost.isPrunable) return
  await update($, offsets, all => ({ ...all, 'map:bag': 0 }))
  if (outpost.isHere) return void (await update($, mapView, (): MapView => ({ view: 'bag', via: 'outposts' })))
  await update($, outpostBag, () => ({ root: path, items: [] }))
  await update($, mapView, (): MapView => ({ view: 'bag', root: path, via: 'outposts' }))
  const status = await $.process.run(outpostArgv.status(path)).catch(() => undefined)
  const items = status?.exitCode === 0 ? await loadBag($, status.stdout, path, path) : []
  // A later outpost opened while this one loaded keeps its own bag.
  if ((await read($, mapView)).root !== path) return
  await update($, outpostBag, () => ({ root: path, items }))
}

// Opens one bag item's diff in the map tab's window, keeping where its bag came from (`root`, `via`).
async function inspectChange($: EngineInterface, path: string, from: Pick<MapView, 'root' | 'via'>) {
  const { root } = from
  const items = root === undefined ? await read($, bag) : ((await read($, outpostBag))?.items ?? [])
  const item = items.find(one => one.path === path) ?? { path, status: 'M' as const }
  await update($, inspect, () => null)
  const keep = { ...(from.root === undefined ? {} : { root: from.root }), ...(from.via === undefined ? {} : { via: from.via }) }
  await update($, mapView, (): MapView => ({ view: 'diff', path, ...keep }))
  await update($, offsets, all => ({ ...all, 'map:diff': 0 }))
  const cwd = root ?? (await toplevel($))
  const ran = await $.process.run(diffArgv(item), cwd === undefined ? {} : { cwd }).catch(() => undefined)
  // `git diff --no-index` exits 1 when the files differ, which is the point.
  const lines = ran === undefined || ran.exitCode > 1 ? [] : ran.stdout.split('\n')
  // Another diff opened while this one ran keeps the window.
  const shown = await read($, mapView)
  if (shown.view !== 'diff' || shown.path !== path || shown.root !== root) return
  await update($, inspect, () => ({ path, lines: lines.slice(0, DIFF_LINES), isCut: lines.length > DIFF_LINES }))
}

// Following: a sent message turns the window to the spell book, where its tool calls show, and then to the tab
// of what the session does: a skill cast to the skills, a summoned pet to the party, a git command to the map.
// A tab the person picks, or anything they do in the pane, holds the window until their next message;
// `/hud follow` turns it off, kept across sessions.
const FOLLOW_KEY = 'follow'
const follow = { isOn: true, isHeld: false }

async function followTo($: EngineInterface, to: Tab) {
  if (!follow.isOn || follow.isHeld || (await read($, isHelpOpen))) return
  // A tab picked while the help check was pending still holds the window.
  await update($, tab, current => (follow.isHeld ? current : to))
}

// Adds a pet to the party and counts the summon; a pet already there under the same agent (one met through its
// tool calls before its spawn answered) is replaced, keeping what it has done, and not counted twice.
async function joinParty($: EngineInterface, pet: Pet) {
  const before = (await read($, pets)).find(one => one.agentId !== undefined && one.agentId === pet.agentId)
  const joined = before === undefined ? pet : { ...pet, actions: before.actions, lastTool: before.lastTool, lastSummary: before.lastSummary, startedAt: before.startedAt }
  await update($, pets, list =>
    [...list.filter(one => one.id !== pet.id && (pet.agentId === undefined || one.agentId !== pet.agentId)), joined].slice(-50),
  )
  if (before !== undefined) return
  await update($, tally, t => ({ ...t, petsSummoned: t.petsSummoned + 1 }))
  $.ui.toast(`🐾 ${speciesFor(petSeed(pet)).name} summoned: ${pet.description}`)
  await followTo($, 'pets')
}

// A subagent met through its tool calls with no spawn of its own seen: a skill's fork or a teammate, which the
// session's agent list names. A loop it does not name is the engine's own fork (compaction, memory) or a subagent
// whose spawn has not answered yet: no pet of the party, so false.
async function discoverPet($: EngineInterface, agentId: string): Promise<boolean> {
  const info = (await $.agent.list().catch(() => [])).find(agent => agent.id === agentId)
  if (info === undefined) return false
  await joinParty($, {
    id: `agent:${agentId}`,
    agentId,
    kind: info.type ?? 'fork',
    description: info.description || info.name || 'a task in the background',
    startedAt: await $.clock.now(),
    status: 'run',
    actions: 0,
  })
  return true
}

// An Agent call answered with its launch, not its answer: the agent runs on in the background (or remotely).
const isLaunched = (ran: { result?: unknown }) => {
  const status = (ran.result as { status?: unknown } | undefined)?.status
  return status === 'async_launched' || status === 'remote_launched'
}

// Pets still questing that the agent list no longer names: engine forks an older build let in, never to finish.
async function dropStrayPets($: EngineInterface) {
  const listed = await $.agent.list().catch(() => undefined)
  if (listed === undefined) return
  const ids = new Set(listed.map(agent => agent.id))
  await update($, pets, list => list.filter(pet => pet.status !== 'run' || pet.agentId === undefined || ids.has(pet.agentId)))
}

// Where back leads from a bag: the outposts list for a bag opened there, the map otherwise.
const isFromOutposts = (view: Pick<MapView, 'root' | 'via'>) => view.root !== undefined || view.via === 'outposts'

// The outpost (worktree) a pet works in: a worktree of its own wherever it sits (`<repo>/.claude/worktrees/…`
// included), one of the outposts other than the session's own folder, or any folder outside the session's
// repository. Its own folder or a folder inside it is no camp. Paths come with their links resolved.
export const campFor = (pet: { cwd?: string; isIsolated: boolean }, outpostsNow: readonly Outpost[], root?: string) => {
  if (pet.isIsolated) return pet.cwd === undefined ? 'worktree' : baseName(pet.cwd)
  if (pet.cwd === undefined) return undefined
  const { cwd } = pet
  const outpost = outpostsNow.find(one => one.realPath === cwd)
  if (outpost !== undefined) return outpost.isHere ? undefined : outpost.name
  const isInside = root !== undefined && (cwd === root || cwd.startsWith(`${root}/`))
  return isInside ? undefined : baseName(cwd)
}

async function campOfPet($: EngineInterface, cwd: string | undefined, isIsolated: boolean) {
  const realCwd = cwd === undefined ? undefined : await realOf($, cwd)
  const root = await toplevel($)
  return campFor(
    { ...(realCwd === undefined ? {} : { cwd: realCwd }), isIsolated },
    await read($, outposts),
    root === undefined ? undefined : await realOf($, root),
  )
}

const refreshAll = ($: EngineInterface) =>
  Promise.all([refreshVitals($), refreshLoadout($), refreshMap($)]).then(() => undefined)

// Sets the session's class and announces it.
async function chooseClass($: EngineInterface, id: string) {
  const hero = classOf(id)
  await update($, heroClass, () => hero.id)
  $.ui.toast(`⚔ Today Claude plays the ${hero.title.toLowerCase()}: ${hero.ranks[0]}`)
}

async function castSkill($: EngineInterface, name: string) {
  const now = await $.clock.now()
  await update($, skillCasts, casts => ({ ...casts, [name]: now }))
  void advance($, p => ({ ...p, skillUses: { ...p.skillUses, [name]: (p.skillUses[name] ?? 0) + 1 } }))
}

// The toast a background pet's return raises: what it brought back, or that it fell.
export const returnToast = (pet: Pick<Pet, 'id' | 'agentId' | 'description' | 'loot'>, status: Pet['status']): string => {
  const name = speciesFor(petSeed(pet)).name
  if (status !== 'ok') return `🐾 ${name} fell: ${pet.description}`
  return `🐾 ${name} returned: ${pet.loot || pet.description}`
}

async function finishPet($: EngineInterface, match: (pet: Pet) => boolean, status: Pet['status'], answer: string) {
  const now = await $.clock.now()
  const finished: Pet[] = []
  await update($, pets, list => {
    // An update may run its change more than once; only the last run's pets count.
    finished.length = 0
    return list.map(pet => {
      if (!match(pet) || pet.status !== 'run') return pet
      const done = { ...pet, status, endedAt: now, loot: firstLine(answer) || pet.loot }
      finished.push(done)
      return done
    })
  })
  // A foreground pet's answer arrives as the call's result; only a background one needs announcing.
  for (const pet of finished) if (pet.isBackground === true) $.ui.toast(returnToast(pet, status))
}

// A shell or monitor a call left running joins the jobs; one the main loop started turns the window there.
async function startJob($: EngineInterface, job: Job) {
  await update($, jobs, list => addJob(list, job))
  if (job.agentId === undefined) await followTo($, 'jobs')
}

// Ends the jobs the engine reports finished, and toasts the ones that failed: the transcript's own notice is
// easy to miss while a turn runs.
async function endJobs($: EngineInterface, ends: readonly JobEnd[]) {
  if (ends.length === 0) return
  const now = await $.clock.now()
  const failed: Job[] = []
  await update($, jobs, list => {
    // An update may run its change more than once; only the last run's jobs count.
    failed.length = 0
    const next = ends.reduce((all, end) => endJob(all, end, now), list)
    for (const job of next) if (job.status === 'err' && list.find(one => one.id === job.id)?.status !== 'err') failed.push(job)
    return trimJobs(next)
  })
  for (const job of failed) $.ui.toast(`⚙ Job failed: ${job.description || job.command}`)
}

// How long a stop pressed once waits for the second press.
const STOP_ARMED_MS = 3000

// A running job's stop asks twice: the first press arms it for a moment, the second stops the job.
async function pressStop($: EngineInterface, job: Job) {
  if ((await read($, stopArmed)) !== job.id) {
    await update($, stopArmed, () => job.id)
    void $.clock
      .sleep(STOP_ARMED_MS)
      .then(() => update($, stopArmed, armed => (armed === job.id ? null : armed)))
      .catch(() => undefined)
    return
  }
  await update($, stopArmed, () => null)
  await stopJob($, job)
}

// TaskStop, the call the model would make, through the permission check.
async function stopJob($: EngineInterface, job: Job) {
  const ran = await $.tool.call({ tool: 'TaskStop', task_id: job.id }).catch(() => undefined)
  if (ran === undefined || ran.isError === true || isRefusal(ran)) {
    $.ui.toast(`⚙ Could not stop: ${job.description || job.command}`)
    return
  }
  await endJobs($, [{ id: job.id, status: 'kill' }])
}

// The pane's animation: blits each tick, stops once a Raster refuses.
const stop = () => {
  anim.ticker?.cancel()
  anim.ticker = undefined
}

// `tick` counts from the moment the mood began, as pickFrame's does.
const frameOf = <T,>(frames: readonly T[], mood: Mood, tick: number): T => frames[Math.floor(tick / FRAME_TICKS[mood]) % frames.length]!

// A class with a portrait shows its bust where the terminal draws cells instead of the picture.
const heroCells = (mood: Mood, tick: number, hero: HeroClassId): string => {
  const busts = PORTRAIT_BUSTS[hero]
  return busts === undefined ? pickFrame(mood, tick, hero) : frameOf(busts[mood], mood, tick)
}

// Whether the terminal draws an Image: unknown until a blit to the drawn portrait answers. One that draws
// its alt instead (a multiplexer without kitty's placeholder images) refuses the blit.
let canDrawImage: boolean | undefined
const PROBE_MS = 500
let probe: Timer | undefined

// Every frame of a class's portrait as PNG base64, read once. A read that fails leaves the bust, and is not
// tried again: a missing picture costs the portrait, never the pane.
const portraits = new Map<HeroClassId, Record<Mood, string[]> | null>()
const portraitFrames = async ($: EngineInterface, hero: HeroClassId): Promise<Record<Mood, string[]> | undefined> => {
  if (portraits.has(hero)) return portraits.get(hero) ?? undefined
  // Inline bytes rather than a file: a multiplexer may forward kitty graphics yet not file transmission.
  const read = (mood: Mood) =>
    Promise.all(
      Array.from({ length: PORTRAIT_FRAMES[mood] }, async (_, n) => {
        const { base64 } = await $.fs.read(`${$.plugin.root}/assets/portraits/${hero}/${mood}-${n}.png`, { as: 'bytes' })
        return base64
      }),
    )
  const frames = await Promise.all([read('idle'), read('cast'), read('hurt')])
    .then(([idle, cast, hurt]) => ({ idle, cast, hurt }))
    .catch(() => null)
  portraits.set(hero, frames)
  return frames ?? undefined
}

// Each menu icon as pictures, PNG base64, read once: the selected card's and the others' (dimmed). A read that
// fails leaves the half-block icons, and is not tried again.
let menuIcons: Map<Tab, [lit: string, dim: string]> | null | undefined
const menuIconPngs = async ($: EngineInterface): Promise<Map<Tab, [lit: string, dim: string]> | undefined> => {
  if (menuIcons === undefined) {
    const read = async (id: Tab, suffix: string) =>
      (await $.fs.read(`${$.plugin.root}/assets/icons/${id}${suffix}.png`, { as: 'bytes' })).base64
    menuIcons = await Promise.all(
      MENU.map(async (slot): Promise<[Tab, [string, string]]> => [slot.id, [await read(slot.id, ''), await read(slot.id, '-dim')]]),
    )
      .then(entries => new Map<Tab, [string, string]>(entries))
      .catch(() => null)
  }
  return menuIcons ?? undefined
}

// Asks the drawn portrait for a blit of its own picture once the frame is up; a refusal falls back to the
// bust, a success starts the picture's animation. Either way the pane is drawn again to match.
const probeImage = ($: EngineInterface, png: string) => {
  probe ??= $.clock.after(PROBE_MS, async () => {
    probe = undefined
    const done = await $.ui
      .blit({ requestId: PANE, key: 'hero', source: { png }, columns: HERO_CELLS.columns, rows: HERO_CELLS.rows })
      .catch(() => ({ deny: 'blit failed' }))
    canDrawImage = done.deny === undefined
    $.ui.invalidate('ui.render')
  })
}

// A refusal and a failed blit both mean nothing of ours is on screen to paint.
const blit = async ($: EngineInterface, key: string, cells: string, columns: number, rows: number) => {
  const done = await $.ui
    .blit({ requestId: PANE, key, cells, columns, rows })
    .catch(() => ({ deny: 'blit failed' }))
  return done.deny === undefined
}

async function paintHero($: EngineInterface) {
  const now = await $.clock.now()
  const nextMood = pickMood(anim.running, anim.hurtUntil - now)
  if (nextMood === anim.mood) {
    anim.moodTick += 1
  } else {
    anim.mood = nextMood
    anim.moodTick = 0
  }
  if (anim.heroImage) {
    const frames = portraits.get(anim.heroClass)
    if (frames == null) return true
    const png = frameOf(frames[anim.mood], anim.mood, anim.moodTick)
    if (png === anim.shownPng) return true
    const done = await $.ui
      .blit({ requestId: PANE, key: 'hero', source: { png }, columns: HERO_CELLS.columns, rows: HERO_CELLS.rows })
      .catch(() => ({ deny: 'blit failed' }))
    if (done.deny !== undefined) return false
    anim.shownPng = png
    return true
  }
  const cells = heroCells(anim.mood, anim.moodTick, anim.heroClass)
  if (cells === anim.shownCells) return true
  if (!(await blit($, 'hero', cells, HERO_CELLS.columns, HERO_CELLS.rows))) return false
  anim.shownCells = cells
  return true
}

// A pet that refuses its blit has scrolled away; it leaves the animation.
async function paintPets($: EngineInterface) {
  const frame = Math.floor(anim.tick / PET_TICKS)
  for (const [key, pet] of anim.pets) {
    const cells = petCells(pet.seed, 'run', frame)
    if (cells === pet.shown) continue
    if (await blit($, key, cells, PET_COLUMNS, PET_ROWS)) pet.shown = cells
    else anim.pets.delete(key)
  }
}

// The running jobs' marches; a job that refuses its blit has scrolled away and leaves the animation.
async function paintJobs($: EngineInterface) {
  const cells = marchCells(anim.tick)
  for (const [key, job] of anim.jobs) {
    if (cells === job.shown) continue
    if (await blit($, key, cells, MARCH_COLUMNS, 1)) job.shown = cells
    else anim.jobs.delete(key)
  }
}

// The overworld's idle frames; a refusal means it scrolled away, and it leaves the animation.
async function paintOverworld($: EngineInterface) {
  const world = anim.overworld
  if (world === undefined) return
  const cells = world.frames[Math.floor(anim.tick / OVERWORLD_TICKS) % world.frames.length] ?? world.shown
  if (cells === world.shown) return
  if (await blit($, 'overworld', cells, world.columns, world.rows)) world.shown = cells
  else anim.overworld = undefined
}

// The encounter's monster: its moment's frames from the tick the moment began, the last held once it ends.
async function paintBoss($: EngineInterface) {
  const monster = anim.boss
  if (monster === undefined) return
  const step = Math.floor((anim.tick - monster.start) / monster.ticks)
  const cells = monster.frames[monster.loop ? step % monster.frames.length : Math.min(step, monster.frames.length - 1)] ?? monster.shown
  if (cells === monster.shown) return
  if (await blit($, 'boss', cells, monster.columns, monster.rows)) monster.shown = cells
  else anim.boss = undefined
}

// The combo's aura: its sparks climb a step each tick.
async function paintAura($: EngineInterface) {
  const aura = anim.aura
  if (aura === undefined) return
  const cells = aura.frames[anim.tick % aura.frames.length] ?? aura.shown
  if (cells === aura.shown) return
  if (await blit($, 'aura', cells, AURA_COLUMNS, HERO_CELLS.rows)) aura.shown = cells
  else anim.aura = undefined
}

async function paint($: EngineInterface) {
  anim.tick += 1
  const hasPets = anim.tab === 'pets' && anim.pets.size > 0
  const hasMap = anim.tab === 'map' && anim.overworld !== undefined
  const hasJobs = anim.tab === 'jobs' && anim.jobs.size > 0
  // The portrait refusing means the pane is closed: nothing of ours is on screen.
  if (anim.hasHero && !(await paintHero($))) return stop()
  if (hasPets) await paintPets($)
  if (hasMap) await paintOverworld($)
  if (anim.boss !== undefined) await paintBoss($)
  if (anim.aura !== undefined) await paintAura($)
  if (hasJobs) await paintJobs($)
  if (!anim.hasHero && !hasPets && !hasMap && !hasJobs && anim.boss === undefined && anim.aura === undefined) stop()
}

// Each draw of an animated tab starts the clock again if a refusal stopped it.
const startAnim = ($: EngineInterface) => {
  anim.ticker ??= $.clock.every(FRAME_MS, () => void paint($))
}

// The session's camp, when it works in a worktree other than the repository's main folder.
const campOf = (list: readonly Outpost[]): { camp?: string } => {
  const here = list.find(one => one.isHere)
  return here === undefined || here.isMain ? {} : { camp: here.name }
}

// CSS pixels per sprite pixel where sprites are drawings: about one column's width, as a half-block cell is.
const SPRITE_PX = 8

// The hero's frames for a mood as one drawing that animates itself: a class with a portrait draws its bust, the
// same frames a terminal without pictures shows, since the desktop draws no pictures either.
const heroSprite = (hero: HeroClassId, mood: Mood) =>
  spriteSvg(
    (PORTRAIT_BUSTS[hero]?.[mood] ?? HERO_CLASS_FRAMES[hero][mood]).map(cells => cellsToPixels(cells, HERO_CELLS.columns, HERO_CELLS.rows)),
    SPRITE_PX,
    FRAME_MS * FRAME_TICKS[mood],
  )

// Off the terminal nothing blits: when the smoke puff runs out the pane is drawn again, back to the mood under it.
let hurtRedraw: Timer | undefined
// A pet's shot at the boss plays out, then the arena is drawn again without it.
let assistRedraw: Timer | undefined

// --- The menu windows ---

// Every window the menu can show: a tab, or a view inside the map tab.
type PageKey = Tab | 'map:bag' | 'map:diff' | 'map:outposts' | 'help'

// `$` goes beside it as an argument of its own: the engine never lets it ride in an object.
type PageContext = {
  ui: ElementTable
  view: MapView
  // The window's inner width.
  inner: number
  now: number
  Raster: ElementTable<'terminal'>['Raster'] | undefined
  // Whether the page draws on the terminal, where a button can hold a row's columns.
  isTerminal: boolean
  callList: ToolCall[]
  petList: Pet[]
  progress: Progress
  // Where the window stands: the first row it shows and how many it has room for.
  offset: number
  rows: number
}

type TerminalClient = ElementTable<'terminal'>['Client']

// Rows the window draws as a list to pick from: a Client on the terminal, so a click anywhere on a row acts on
// it; a column of buttons elsewhere. The Clients all take `{ rows, width }`.
type PickList<Row> = {
  key: string
  rows: readonly Row[]
  // The terminal's Client for the shown rows; its module must be spelled out where it is drawn.
  client: (Client: TerminalClient, props: { rows: Row[]; width: number }, height: number) => RenderChildren
  // A row's button on surfaces with no Client; undefined leaves it a blank line.
  button: (row: Row) => { key: string; label: string; dimColor?: boolean; onPress: () => void } | undefined
}

// What a window shows: its own title when not the tab's, the subtitle, and either items it pages itself or a
// list to pick from; `actions` sit on its title row.
type Page = {
  title?: string
  subtitle: string
  items?: Item[]
  list?: PickList<never>
  actions?: RenderChildren
}

const pickList = <Row,>(list: PickList<Row>): PickList<never> => list as unknown as PickList<never>

// The scrolled slice of a pick list, drawn for the surface.
function pickBody($: EngineInterface, e: { surface: string }, list: PickList<never>, offset: number, rows: number, inner: number) {
  const start = clampOffset(offset, list.rows.length, rows)
  const shown = list.rows.slice(start, start + rows)
  const total = list.rows.length
  const ui = $.ui.resolve(e as never) as ElementTable
  if (e.surface === 'terminal') {
    const { Client } = ui as ElementTable<'terminal'>
    return { node: list.client(Client, { rows: shown, width: inner }, rows), total }
  }
  const { Box, Button } = ui
  return {
    node: (
      <Box flexDirection="column">
        {shown.map((row, index) => {
          const button = list.button(row)
          return button === undefined ? (
            <Box key={`${list.key}-${index}`} height={1} />
          ) : (
            <Button key={button.key} label={button.label} plain {...(button.dimColor === undefined ? {} : { dimColor: button.dimColor })} onPress={button.onPress} />
          )
        })}
      </Box>
    ),
    total,
  }
}

const backToMap = ($: EngineInterface) => void update($, mapView, (): MapView => ({ view: 'map' }))

const spellsPage = async ($: EngineInterface, { ui, inner, callList }: PageContext): Promise<Page> => {
  const filter = await read($, spellFilter)
  const casts = await read($, castCount)
  return {
    items: spellItems(ui, callList, inner, filter),
    subtitle: filter === 'all' ? `${casts} casts` : `${filterSpells(callList, filter).length} of ${casts} casts`,
    ...(callList.length === 0
      ? {}
      : {
          actions: spellFilters(ui, callList, filter, picked => {
            void update($, spellFilter, () => picked)
            void update($, offsets, all => ({ ...all, spells: 0 }))
          }),
        }),
  }
}

const petsPage = async (_$: EngineInterface, { ui, inner, now, Raster, petList }: PageContext): Promise<Page> => ({
  items: petItems(ui, petList, now, inner, Raster),
  subtitle: partySubtitle(petList),
})

// The local clock's offset from UTC, read once a session from `date`; UTC until it answers.
let utcOffsetMs = 0
export const parseUtcOffset = (text: string): number | undefined => {
  const match = /^([+-])(\d{2})(\d{2})$/.exec(text.trim())
  if (match === null) return undefined
  return (match[1] === '-' ? -1 : 1) * (Number(match[2]) * 60 + Number(match[3])) * 60_000
}
async function readUtcOffset($: EngineInterface) {
  const ran = await $.process.run(['date', '+%z']).catch(() => undefined)
  const offset = ran?.exitCode === 0 ? parseUtcOffset(ran.stdout) : undefined
  if (offset !== undefined) utcOffsetMs = offset
}
export const localHour = (now: number, offsetMs: number): number => Math.floor(((now + offsetMs) % 86_400_000 + 86_400_000) % 86_400_000 / 3_600_000)

const mapPage = async ($: EngineInterface, { ui, inner, now, Raster }: PageContext): Promise<Page> => {
  const world = await read($, map)
  const list = await read($, outposts)
  const hero = classOf(await read($, heroClass))
  const fx = await read($, mapFx)
  return {
    items: mapItems(ui, world, await read($, touched), inner, {
      openBag: () => {
        void update($, mapView, (): MapView => ({ view: 'bag' }))
        void update($, offsets, all => ({ ...all, 'map:bag': 0 }))
      },
      openOutposts: () => {
        void update($, mapView, (): MapView => ({ view: 'outposts' }))
        void surveyOutposts($).catch(() => undefined)
      },
      outposts: list.length,
      camps: Object.fromEntries(list.filter(one => !one.isHere && one.branch !== '').map(one => [one.branch, one.name])),
      heroColor: hero.color,
      ...(Raster === undefined ? {} : { Raster }),
      phase: phaseOf(localHour(now, utcOffsetMs)),
      isCasting: anim.running > 0,
      weather: weatherOf(await read($, boss), await read($, bossFx), now),
      ...(fx !== null && now - fx.at < MAP_FX_MS ? { event: fx.event } : {}),
    }),
    subtitle: mapSubtitle(world),
  }
}

const diffPage = async ($: EngineInterface, { ui, view, inner }: PageContext): Promise<Page> => {
  const opened = await read($, inspect)
  const source = view.root === undefined ? await read($, bag) : ((await read($, outpostBag))?.items ?? [])
  return {
    title: '🔍 INSPECT',
    items: inspectItems(ui, opened, source.find(item => item.path === view.path), inner, () => {
      void update($, mapView, (): MapView => ({ ...view, view: 'bag', path: undefined }))
    }),
    subtitle: view.path ?? '',
  }
}

const outpostsPage = async ($: EngineInterface): Promise<Page> => {
  const list = await read($, outposts)
  const rows: OutpostRow[] = [{ kind: 'back' }, ...list.map(outpost => ({ kind: 'outpost' as const, outpost }))]
  if (list.length === 0) rows.push({ kind: 'note', text: 'No outposts: this repository has one worktree.' })
  return {
    title: '🏕 OUTPOSTS',
    subtitle: `${list.length} camps · ${list.filter(one => one.dirty > 0).length} with unsaved work`,
    list: pickList<OutpostRow>({
      key: 'outposts',
      rows,
      client: (Client, props, height) => <Client key="outposts" module="./outposts-client.tsx" props={props satisfies OutpostsProps} width={props.width} height={height} />,
      button: row => {
        if (row.kind === 'back') return { key: 'outposts-back', label: '◂ back to the map', onPress: () => backToMap($) }
        if (row.kind !== 'outpost' || row.outpost.isPrunable) return undefined
        const { path, name } = row.outpost
        return { key: `outpost-${path}`, label: `⚑ ${name}`, onPress: () => void openOutpost($, path) }
      },
    }),
  }
}

const bagPage = async ($: EngineInterface, { view }: PageContext): Promise<Page> => {
  const opened = view.root === undefined ? undefined : await read($, outpostBag)
  const items = view.root === undefined ? await read($, bag) : opened?.root === view.root ? opened.items : []
  const rows: BagRow[] = [
    { kind: 'back', ...(isFromOutposts(view) ? { label: 'the outposts' } : {}) },
    ...(items.length === 0 ? [{ kind: 'note' as const, text: 'The bag is empty: every change is committed.' }] : []),
    ...items.map(item => ({ kind: 'item' as const, item })),
  ]
  return {
    title: '🎒 INVENTORY',
    subtitle: view.root === undefined ? bagSubtitle(items) : `⚑${baseName(view.root)} · ${bagSubtitle(items)}`,
    list: pickList<BagRow>({
      key: 'bag',
      rows,
      client: (Client, props, height) => <Client key="bag" module="./bag-client.tsx" props={props satisfies BagProps} width={props.width} height={height} />,
      button: row => {
        if (row.kind === 'back') {
          return { key: 'bag-back', label: '◂ back', onPress: () => void update($, mapView, (): MapView => ({ view: isFromOutposts(view) ? 'outposts' : 'map' })) }
        }
        if (row.kind !== 'item') return undefined
        const { path } = row.item
        return { key: `bag-${path}`, label: path, onPress: () => void inspectChange($, path, view) }
      },
    }),
  }
}

// Fills the prompt with `text`, or toasts `fallback` when the prompt cannot take it.
const fillPrompt = ($: EngineInterface, text: string, fallback: string) =>
  void $.prompt
    .fill({ text })
    .then(filled => (filled.isFilled ? undefined : $.ui.toast(fallback)))
    .catch(() => undefined)

// Fills the prompt with a skill's command, or says how to cast it when the prompt cannot take it.
const castFromPage = ($: EngineInterface, name: string) => fillPrompt($, castText(name), `Type /${name} to cast it`)

const skillsPage = async ($: EngineInterface, { ui, inner, now, progress: progressNow, isTerminal }: PageContext): Promise<Page> => {
  const gear = await read($, loadout)
  const rows = skillRows({
    loadout: gear,
    progress: progressNow,
    casts: await read($, skillCasts),
    now,
    isSealedOpen: await read($, isSealedOpen),
  })
  return {
    subtitle: skillsSubtitle(gear, progressNow),
    items: skillItems(ui, rows, inner, isTerminal, name => castFromPage($, name), () => void update($, isSealedOpen, open => !open)),
  }
}

const jobsPage = async ($: EngineInterface, { ui, inner, now, Raster }: PageContext): Promise<Page> => {
  const list = await read($, jobs)
  const armed = await read($, stopArmed)
  return { items: jobItems(ui, list, now, inner, job => void pressStop($, job), armed, Raster), subtitle: jobsSubtitle(list) }
}

const helpPage = async ($: EngineInterface, { ui }: PageContext): Promise<Page> => ({
  title: '❓ HELP',
  subtitle: `${HELP_COMMANDS.length} commands`,
  items: helpItems(ui, () => void update($, isHelpOpen, () => false)),
})

// The window a menu entry, a view inside the map tab, or the help page shows.
function pageFor($: EngineInterface, key: PageKey, ctx: PageContext): Promise<Page> {
  switch (key) {
    case 'spells':
      return spellsPage($, ctx)
    case 'pets':
      return petsPage($, ctx)
    case 'map':
      return mapPage($, ctx)
    case 'map:diff':
      return diffPage($, ctx)
    case 'map:outposts':
      return outpostsPage($)
    case 'map:bag':
      return bagPage($, ctx)
    case 'skills':
      return skillsPage($, ctx)
    case 'jobs':
      return jobsPage($, ctx)
    case 'help':
      return helpPage($, ctx)
  }
}

// The session's adventure log for /hud recap.
// Every figure counts from the HUD's watch start, so the duration and the tally agree.
async function recap($: EngineInterface) {
  await refreshVitals($).catch(() => undefined)
  const now = await $.clock.now()
  const casts = await read($, castCount)
  const callList = (await read($, calls)).map(normalizeCall)
  const since = await read($, startedAt)
  const vitalsNow = await read($, vitals)
  return recapText({
    hero: classOf(await read($, heroClass)),
    level: heroStats(callList, casts).level,
    casts,
    calls: callList,
    ...(since === 0 ? {} : { elapsedMs: now - since }),
    tally: await read($, tally),
    bestCombo: (await read($, combo)).best,
    boss: await read($, boss),
    touched: await read($, touched),
    ...(vitalsNow.usd === undefined ? {} : { usd: vitalsNow.usd }),
    ...(vitalsNow.contextPercent === undefined ? {} : { contextPercent: vitalsNow.contextPercent }),
  })
}

// Moves a window `by` rows within its items: `view` is the window as last drawn, its key, rows in all and room.
// A window that shows all it has is left alone, so a scroll key there writes nothing.
const scrollWindow = async ($: EngineInterface, view: { key: string; total: number; rows: number; stops?: number[] }, by: number) => {
  if (view.total <= view.rows) return
  await update($, offsets, all => ({ ...all, [view.key]: scrolledOffset(all[view.key] ?? 0, by, view.total, view.rows, view.stops) }))
}

export const register: Register = on => {
  // The last drawn log window; scrolling clamps against it.
  // `key` names the window being scrolled: a tab, or `map:bag` / `map:diff` inside the map tab.
  let layout: { rows: number; total: number; key: string; stops?: number[] } = { rows: 1, total: 0, key: 'spells' }
  // Agent calls asked to run in a worktree of their own, by tool_use_id, until their spawn.
  const isolated = new Set<string>()
  // The skill a typed slash command just cast, until the prompt it may also submit: counted once, not twice.
  let commandCast: string | undefined
  // Agent calls sent to run in the background, by tool_use_id, until their spawn.
  const background = new Set<string>()
  // Subagents being looked up in the agent list, so parallel tool calls of one add it once.
  const discovering = new Set<string>()
  // What the loops the agent list does not name have done: a spawn that answers later takes it on, an engine fork
  // never shows.
  const strays = new Map<string, Pick<Pet, 'actions' | 'startedAt' | 'lastTool' | 'lastSummary'>>()
  // Calls auto mode denied, by tool_use_id, until their tool.call answers.
  const autoDenied = new Set<string>()
  // The loop whose tool `waitingFor` names: a subagent's id, undefined for the main loop.
  let waitingAgent: string | undefined

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: COMMAND,
      description:
        'Open the adventure HUD (args: spell, party, map, skill, jobs or 1-5; class [name] rerolls; cards toggles edit cards; follow toggles turning to the tab of what happens; recap sums up the session; help lists them all)',
    })
    await markStart($)
    await loadProgress($)
    void readUtcOffset($).catch(() => undefined)
    // A tab kept from an older build (`feats`) no longer names a page: the spell book stands in.
    await update($, tab, kept => (isTab(kept) ? kept : 'spells'))
    await dropStrayPets($)
    follow.isOn = (await $.store.get(FOLLOW_KEY).catch(() => undefined)) !== false
    // Each session plays a class at random; a reload of the mod keeps the one rolled.
    if ((await read($, heroClass)) === '') await chooseClass($, rollClass(Math.random()))
    void refreshAll($).catch(() => undefined)
    void $.ui.open({ id: PANE, title: TITLE })

    return next(e)
  })

  // A /clear or an in-session /resume moves to another session without session.start.
  on('classic.SessionStart', async ($, e, next) => {
    if (e.source === 'clear' || e.source === 'resume') {
      await resetSession($)
      void refreshAll($).catch(() => undefined)
    }
    return next(e)
  })

  // A slash command the person typed is a message of theirs, even one that never reaches the conversation (a
  // skill forked to the background): the window follows again, and a skill counts as cast.
  on('command.run', async ($, e, next) => {
    // A forked skill never submits its prompt, so its mark ends with the next command rather than outliving it.
    commandCast = undefined
    const isPerson = e.origin?.kind === 'composer' || e.origin?.kind === 'bridge'
    if (!isPerson || e.command === COMMAND) return next(e)
    follow.isHeld = false
    const isSkill = (await read($, loadout)).skills.some(slot => slot.name === e.command)
    if (isSkill) {
      commandCast = e.command
      await castSkill($, e.command)
      await followTo($, 'skills')
    }
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    // A tab is named as its card shows it (`/hud party`, any case) or by its number there (`/hud 2`); its id
    // (`pets`) still works.
    const typed = e.args.trim()
    const arg = MENU.find((entry, index) => slotKey(index) === typed || entry.label.toLowerCase() === typed.toLowerCase())?.id ?? typed
    if (arg === 'class' || arg.startsWith('class ')) {
      const asked = arg.slice('class'.length).trim()
      if (asked !== '' && !isClassId(asked)) return { text: `No such class. Pick one of: ${CLASS_IDS.join(', ')}.` }
      const current = await read($, heroClass)
      const next = asked === '' ? rollClass(Math.random(), current) : asked
      await chooseClass($, next)
      return { text: `Claude is now a ${classOf(next).title.toLowerCase()}.` }
    }
    if (arg === 'recap') return { text: await recap($) }
    if (arg === 'cards') {
      const isOn = (await $.store.get(CARDS_KEY)) !== false
      await $.store.set(CARDS_KEY, !isOn)
      return { text: isOn ? 'Edit cards off: edits draw as before.' : 'Edit cards on.' }
    }
    if (arg === 'help') return { text: helpText() }
    if (arg === 'follow') {
      follow.isOn = !follow.isOn
      await $.store.set(FOLLOW_KEY, follow.isOn)
      return { text: follow.isOn ? 'The HUD follows the action to its tab.' : 'The HUD stays on the tab you pick.' }
    }
    if (isTab(arg)) {
      follow.isHeld = true
      await update($, tab, () => arg)
      await update($, isHelpOpen, () => false)
    }
    await $.ui.open({ id: PANE, title: TITLE })

    return { text: 'Adventure HUD opened.' }
  })

  // Auto mode's classifier denied a call: a refusal, known by the call's id rather than by its wording.
  on('classic.PermissionDenied', async ($, e, next) => {
    autoDenied.add(e.tool_use_id)
    return next(e)
  })

  // A permission prompt is about to ask the person; the panel says so until that tool is done. A hook beneath
  // that decides leaves no prompt to wait on.
  on('classic.PermissionRequest', async ($, e, next) => {
    const result = await next(e)
    if (result.decision === undefined) {
      waitingAgent = e.agent_id
      const tool = e.tool_name
      await update($, waitingFor, () => tool)
    }
    return result
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, waitingFor, () => null)
    // A background task's notification says a job ended, and how. It is no message of the person's: a tab they
    // picked stays held, and the window stays where it is.
    if (e.origin?.kind === 'task-notification') {
      await endJobs($, parseJobEnds(e.text))
      return next(e)
    }
    // The HUD's own command is no message: `/hud map` and the like set the window themselves.
    if (skillOfPrompt(e.text, [COMMAND]) === COMMAND) return next(e)
    // A new message lets the window follow again, whatever tab was picked during the last.
    follow.isHeld = false
    const known = (await read($, loadout)).skills.map(slot => slot.name)
    const skill = skillOfPrompt(e.text, known)
    // A skill its slash command already counted is not counted again.
    if (skill !== undefined && skill !== commandCast) await castSkill($, skill)
    commandCast = undefined
    await followTo($, skill === undefined ? 'spells' : 'skills')
    return next(e)
  })

  // The main loop stopping lists the background work still in flight: the jobs are checked against it.
  on('classic.Stop', async ($, e, next) => {
    const inFlight = e.background_tasks
    if (inFlight !== undefined) {
      const now = await $.clock.now()
      await update($, jobs, list => reconcileJobs(list, inFlight, now))
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) {
      const agentId = e.agentId
      await finishPet($, pet => pet.agentId === agentId, e.isAborted ? 'err' : 'ok', 'answer' in e ? e.answer : '')
      return next(e)
    }
    // An interrupted prompt leaves nothing waiting on the person.
    await update($, waitingFor, () => null)
    // The turn's winnings wait for the line that closes it.
    const won = await read($, turnLoot)
    await update($, turnLoot, () => EMPTY_LOOT)
    const durationMs = e.durationMs
    if (lootText(won) !== '') await update($, unclaimedLoot, list => [...list, { ...won, durationMs }].slice(-KEPT_UNCLAIMED))
    // The outposts list, while open, is surveyed again after each turn.
    const isSurveying = (await read($, mapView)).view === 'outposts'
    void refreshAll($)
      .then(() => (isSurveying ? surveyOutposts($) : undefined))
      .catch(() => undefined)
    return next(e)
  })

  // A compaction of the main conversation is a night at the inn: the MP left before it pours back to what the
  // window holds now, the panel drawn over and over while it fills.
  on('session.compact', async ($, e, next) => {
    const before = manaLeft(await read($, vitals))
    const result = await next(e)
    if (e.trigger === 'precompute' || e.agentId !== undefined || result.skip !== undefined) return result
    const at = await $.clock.now()
    await update($, restFx, () => (before === undefined ? { at } : { at, from: before }))
    await refreshVitals($).catch(() => undefined)
    $.ui.toast('🌙 Rested at the inn: MP restored')
    const pour = $.clock.every(REST_FRAME_MS, () => $.ui.invalidate('ui.render'))
    $.clock.after(REST_MS, () => {
      pour.cancel()
      $.ui.invalidate('ui.render')
    })
    return result
  })

  on('agent.spawn', async ($, e, next) => {
    const ran = await next(e)
    const isIsolated = isolated.delete(e.tool_use_id)
    const isBackground = background.delete(e.tool_use_id)
    if (ran.agentId === undefined) return ran
    const now = await $.clock.now()
    // A pet sent to its own worktree, or to a folder outside the repository, camps there.
    const camp = await campOfPet($, e.cwd, isIsolated)
    const stray = strays.get(ran.agentId)
    strays.delete(ran.agentId)
    const pet: Pet = {
      id: e.tool_use_id,
      agentId: ran.agentId,
      kind: e.subagentType,
      description: e.description,
      startedAt: now,
      status: 'run',
      actions: 0,
      ...stray,
      ...(camp === undefined ? {} : { camp }),
      ...(isBackground ? { isBackground } : {}),
    }
    await joinParty($, pet)
    return ran
  })

  on('tool.call', async ($, e, next) => {
    // The HUD's own calls (a job's stop button) are none of the hero's: no cast, no combo, no level.
    if (next.origin.plugin === PLUGIN) return next(e)
    const isMain = e.agentId === undefined
    // A mod loaded mid-session starts its watch at the first call it sees.
    await markStart($)
    const startedAt = await $.clock.now()
    const summary = summarize(e)
    const call: ToolCall = { id: e.tool_use_id, tool: e.tool, summary, startedAt, status: 'run' }

    // A foreground Agent call returns with its pet's answer; a background one returns at once.
    const isBackground = (e as { run_in_background?: unknown }).run_in_background === true
    if (e.tool === 'Agent' && (e as { isolation?: unknown }).isolation === 'worktree') isolated.add(e.tool_use_id)
    if (e.tool === 'Agent' && isBackground) background.add(e.tool_use_id)
    // A question to the person waits on them while it is open.
    if (e.tool === 'AskUserQuestion') {
      waitingAgent = e.agentId
      await update($, waitingFor, () => e.tool)
    }
    if (isMain) {
      await update($, calls, list => [...list, call].slice(-200))
      await update($, castCount, count => count + 1)
      anim.running += 1
    } else if (e.agentId !== undefined) {
      const agentId = e.agentId
      const stray = strays.get(agentId)
      if (stray !== undefined) {
        strays.set(agentId, { ...stray, actions: stray.actions + 1, lastTool: e.tool, lastSummary: summary })
      } else if (!(await read($, pets)).some(pet => pet.agentId === agentId) && !discovering.has(agentId)) {
        discovering.add(agentId)
        const isPet = await discoverPet($, agentId).finally(() => discovering.delete(agentId))
        if (!isPet) strays.set(agentId, { actions: 1, startedAt, lastTool: e.tool, lastSummary: summary })
      }
      await update($, pets, list =>
        list.map(pet =>
          pet.agentId === agentId ? { ...pet, actions: pet.actions + 1, lastTool: e.tool, lastSummary: summary } : pet,
        ),
      )
    }

    let ran: Awaited<ReturnType<typeof next>>
    let isAutoDenied = false
    try {
      ran = await next(e)
    } finally {
      if (isMain) anim.running -= 1
      // Auto mode denies while the call is under way; answered or not, its mark goes with it.
      isAutoDenied = autoDenied.delete(e.tool_use_id)
      // An Agent call that never spawned (refused, interrupted) leaves no mark behind.
      if (e.tool === 'Agent') {
        isolated.delete(e.tool_use_id)
        background.delete(e.tool_use_id)
      }
      // Run or refused, the tool a prompt asked about no longer waits on the person; the same tool in another
      // loop is not the one asked about.
      if (waitingAgent === e.agentId && (await read($, waitingFor)) === e.tool) await update($, waitingFor, () => null)
    }
    // A refused call never ran: the hero takes no hurt, the combo and the turn's streak stand.
    const isRefused = isAutoDenied || isRefusal(ran)
    const isError = !isRefused && ran.isError === true
    const status: ToolCallStatus = isRefused ? 'deny' : isError ? 'err' : 'ok'

    // The world reacts to every loop's calls: files explored, bosses fought.
    // NotebookEdit names its file `notebook_path`.
    const fields = e as { file_path?: unknown; notebook_path?: unknown }
    const filePath = fields.file_path ?? fields.notebook_path
    if (typeof filePath === 'string' && !isRefused && (e.tool === 'Read' || EDIT_TOOLS.has(e.tool))) {
      const cwd = await $.session.cwd()
      const path = filePath.startsWith(`${cwd}/`) ? filePath.slice(cwd.length + 1) : filePath
      await update($, touched, list => touchFile(list, path, EDIT_TOOLS.has(e.tool)))
      if (EDIT_TOOLS.has(e.tool)) void refreshMap($, 'files').catch(() => undefined)
      if (isMain && !isError && EDIT_TOOLS.has(e.tool)) await update($, turnLoot, loot => forge(loot, path))
    }
    let feat: ToolCall['feat']
    if (e.tool === 'Bash' && !isRefused) {
      const command = e.command
      const before = await read($, boss)
      const fight = fightBoss(before, command, isError, ran.text ?? '')
      await update($, boss, () => fight.boss)
      const fought = fight.event === 'defeat' ? before : fight.boss
      if (fight.event !== undefined && fought !== null) {
        const at = await $.clock.now()
        const damage = fight.event === 'hit' && before !== null && fight.boss !== null ? before.hp - fight.boss.hp : 0
        await update($, bossFx, (): BossFx => ({ event: fight.event!, at, damage, boss: fought }))
        // The card plays the moment, then settles (or, the boss slain, goes).
        $.clock.after(FX_MS[fight.event], () => $.ui.invalidate('ui.render'))
      }
      if (fight.event === 'appear' && fight.boss !== null) {
        $.ui.toast(`☠ ${fight.boss.name} appears! HP ${fight.boss.hp}`)
      }
      if (fight.event === 'enrage' && fight.boss !== null) {
        $.ui.toast(`🔥 ${fight.boss.name} is enraged! Nothing has landed on it`)
      }
      if (fight.event === 'defeat') {
        feat = 'slay'
        $.ui.toast('⚔ Boss defeated!')
        // The rainbow over the map fades once its while is up.
        $.clock.after(RAINBOW_MS, () => $.ui.invalidate('ui.render'))
        await update($, tally, t => ({ ...t, bossesDefeated: t.bossesDefeated + 1 }))
        await update($, turnLoot, loot => ({ ...loot, bosses: loot.bosses + 1 }))
      }
      // A commit saves on the map, a push delivers to the castle; a failed one does neither.
      const gitEvent = isError ? undefined : gitEventOf(command)
      if (gitEvent !== undefined) {
        feat ??= gitEvent
        const at = await $.clock.now()
        await update($, mapFx, (): MapFx => ({ event: gitEvent, at }))
        $.ui.toast(gitEvent === 'deliver' ? '🏰 Loot delivered to the castle!' : '💾 Progress saved')
        $.clock.after(MAP_FX_MS, () => $.ui.invalidate('ui.render'))
      }
      if (runsGit(command)) {
        void refreshMap($).catch(() => undefined)
        if (isMain) await followTo($, 'map')
      }
    }
    // A shell or monitor left running in the background (asked to, ctrl+b, a timeout) becomes a job.
    if ((e.tool === 'Bash' || e.tool === 'Monitor') && !isRefused && !isError) {
      const result = ran.result as { backgroundTaskId?: unknown; taskId?: unknown } | undefined
      const id = e.tool === 'Bash' ? result?.backgroundTaskId : result?.taskId
      if (typeof id === 'string') {
        await startJob($, {
          id,
          toolUseId: e.tool_use_id,
          kind: e.tool === 'Bash' ? 'shell' : 'monitor',
          command: e.tool === 'Bash' ? e.command : (e.command ?? e.ws?.url ?? ''),
          description: e.description ?? '',
          startedAt,
          status: 'run',
          ...(e.agentId === undefined ? {} : { agentId: e.agentId }),
        })
      }
    }
    if (e.tool === 'TaskStop' && !isRefused && !isError) {
      const id = (ran.result as { task_id?: unknown } | undefined)?.task_id
      if (typeof id === 'string') await endJobs($, [{ id, status: 'kill' }])
    }

    if (!isMain) return ran

    const endedAt = await $.clock.now()
    const ms = Math.round(endedAt - startedAt)
    if (isError) anim.hurtUntil = endedAt + HURT_MS
    if (isError || isRefused) {
      await update($, tally, t => (isError ? { ...t, failures: t.failures + 1 } : { ...t, refusals: t.refusals + 1 }))
    }
    await update($, calls, list =>
      list.map(one => (one.id === call.id ? { ...normalizeCall(one), ms, status, ...(feat === undefined ? {} : { feat }) } : one)),
    )
    // The last heart lost knocks the hero out; the next clean cast revives them with every heart back.
    const fallen = await read($, knockout)
    if (isError && fallen?.state !== 'down') {
      const stood = sinceRevive((await read($, calls)).map(normalizeCall), await read($, revivedBy))
      if (heroStats(stood, stood.length).hp === 0) {
        await update($, knockout, (): Knockout => ({ state: 'down', at: endedAt }))
        $.ui.toast('💀 Claude is knocked out! A clean cast revives them')
      }
    } else if (status === 'ok' && fallen?.state === 'down') {
      await update($, revivedBy, () => call.id)
      await update($, knockout, (): Knockout => ({ state: 'up', at: endedAt }))
      $.ui.toast('✨ Revived! Every heart restored')
      $.clock.after(REVIVE_MS, () => $.ui.invalidate('ui.render'))
    }
    if (!isRefused) await update($, combo, current => {
      const streak = isError ? 0 : current.current + 1
      return { current: streak, best: Math.max(current.best, streak) }
    })

    if (e.tool === 'Agent' && !isBackground && !isRefused) {
      // Without run_in_background, core may still send the agent to the background (its type asks to, or the call
      // ran long): it answers with the launch, and the pet's own turn.complete brings it back.
      if (isLaunched(ran)) {
        await update($, pets, list => list.map(pet => (pet.id === call.id ? { ...pet, isBackground: true } : pet)))
      } else {
        await finishPet($, pet => pet.id === call.id, isError ? 'err' : 'ok', ran.text ?? '')
      }
    }
    if (e.tool === 'Skill' && !isRefused) {
      const skill = (e as { skill?: unknown }).skill
      if (typeof skill === 'string') {
        await castSkill($, skill)
        await followTo($, 'skills')
      }
    }

    // A refused call never ran: it gives back the cast counted at its start and earns no level.
    if (isRefused) {
      await update($, castCount, count => count - 1)
      return ran
    }

    const total = await read($, castCount)
    await update($, turnLoot, loot => ({ ...loot, xp: loot.xp + 1 }))
    if (total % CALLS_PER_LEVEL === 0) {
      const level = 1 + total / CALLS_PER_LEVEL
      await update($, turnLoot, loot => ({ ...loot, level }))
      $.ui.toast(`✦ Level up! Lv.${level} ${rankOf(classOf(await read($, heroClass)), level)}`)
      await update($, flashUntil, () => endedAt + FLASH_MS)
      void $.clock
        .sleep(FLASH_MS)
        .then(() => update($, flashUntil, until => (until <= endedAt + FLASH_MS ? 0 : until)))
        .catch(() => undefined)
    }
    void refreshVitals($).catch(() => undefined)

    return ran
  })

  // A card's icon Client posts `{ select }` when clicked, `{ help }` on ?; the bag and outposts Clients their rows.
  // The person at work in the pane, a press on any of its buttons (their hotkeys too), a row picked in a Client
  // or the wheel, holds the window where they are until their next message: a diff being read stays put.
  on('ui.press', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    follow.isHeld = true
    return next(e)
  })

  on('ui.message', async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    follow.isHeld = true
    const data = (e.data ?? {}) as { select?: unknown; help?: unknown; scroll?: unknown }
    // Each card's icon Client is keyed `icon-<tab>`.
    const isMenu = e.element?.startsWith('icon-') === true
    if (isMenu && typeof data.scroll === 'number') {
      await scrollWindow($, layout, data.scroll)
      return {}
    }
    if (isMenu && data.help === true) {
      await update($, isHelpOpen, open => !open)
      await update($, offsets, all => ({ ...all, help: 0 }))
      return {}
    }
    if (isMenu && typeof data.select === 'string' && isTab(data.select)) {
      const picked = data.select
      await update($, tab, () => picked)
      await update($, isHelpOpen, () => false)
      return {}
    }
    if (e.element === 'bag') {
      const asked = data as { back?: unknown; inspect?: unknown }
      const from = await read($, mapView)
      if (asked.back === true) await update($, mapView, (): MapView => ({ view: isFromOutposts(from) ? 'outposts' : 'map' }))
      if (typeof asked.inspect === 'string') {
        await inspectChange($, asked.inspect, { ...(from.root === undefined ? {} : { root: from.root }), ...(from.via === undefined ? {} : { via: from.via }) })
      }
      return {}
    }
    if (e.element === 'outposts') {
      const asked = data as { back?: unknown; outpost?: unknown }
      if (asked.back === true) await update($, mapView, (): MapView => ({ view: 'map' }))
      if (typeof asked.outpost === 'string') await openOutpost($, asked.outpost)
      return {}
    }
    return next(e)
  })

  // Edit and Write results in the transcript drawn as spell cards; errors and other tools stay the engine's.
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (!CARD_TOOLS.has(e.props.tool) || e.props.isErrored) return next(e)
    if ((await $.store.get(CARDS_KEY).catch(() => undefined)) === false) return next(e)
    const output = e.props.output as Partial<EditOutput> | undefined
    if (typeof output?.filePath !== 'string') return next(e)
    return renderEditCard($.ui.resolve(e), e.props.tool, output as EditOutput, await $.session.cwd())
  })

  // The line closing a turn tells what it won. A line takes the waiting turn its duration matches, once, and keeps
  // it; drawing is pure, so the claim is written just after.
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    const drawn = await next(e)
    let loot = (await read($, claimedLoot))[e.requestId]
    if (loot === undefined) {
      const waiting = await read($, unclaimedLoot)
      const claimed = waiting[claimLoot(waiting, e.props.durationMs)]
      if (claimed === undefined) return drawn
      const { durationMs, ...won } = claimed
      loot = won
      const line = e.requestId
      $.clock.after(0, () => void claim($, line, durationMs, won).catch(() => undefined))
    }
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="row">
        {drawn}
        <Text color="yellow" wrap="truncate"> · {lootText(loot)}</Text>
      </Box>
    )
  })

  // Every window draws only what fits, so the engine has nothing to scroll:
  // the wheel and scroll keys move the active window's items instead.
  on('ui.scroll', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    follow.isHeld = true
    if (layout.total <= layout.rows) return next(e)
    await scrollWindow($, layout, e.by)
    return {}
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const active = await read($, tab)
    const entry = entryOf(active)
    const width = e.props.bodyColumns
    const now = await $.clock.now()
    const ui = $.ui.resolve(e)
    const { Box, Button, Text } = ui
    const Raster = e.surface === 'terminal' ? $.ui.resolve(e).Raster : undefined
    const Svg = e.surface === 'terminal' ? undefined : $.ui.resolve(e).Svg
    anim.tab = active

    const callList = (await read($, calls)).map(normalizeCall)
    const petList = await read($, pets)
    const progressNow = await read($, progress)
    const hero = classOf(await read($, heroClass))
    const bossNow = await read($, boss)
    const waiting = await read($, waitingFor)
    const helpOpen = await read($, isHelpOpen)
    if (anim.heroClass !== hero.id) {
      // A new class: the portrait starts over from its first idle frame.
      anim.heroClass = hero.id
      anim.mood = 'idle'
      anim.moodTick = 0
      anim.shownCells = heroCells('idle', 0, hero.id)
    }
    // Knocked out, the hero lies still in grey; hearts lost before the last revive no longer count.
    const fall = await read($, knockout)
    const isDown = fall?.state === 'down'
    const isRevived = fall?.state === 'up' && now - fall.at < REVIVE_MS
    const lastRevive = await read($, revivedBy)
    const rest = await read($, restFx)
    const downCells = isDown ? drainCells((PORTRAIT_BUSTS[hero.id]?.idle ?? HERO_CLASS_FRAMES[hero.id].idle)[0] ?? '') : undefined
    // A class with a portrait draws it as a picture until the terminal is found not to draw one.
    const portraitSet = !isDown && Raster !== undefined && PORTRAIT_BUSTS[hero.id] !== undefined && canDrawImage !== false ? await portraitFrames($, hero.id) : undefined
    const portrait = portraitSet === undefined ? undefined : frameOf(portraitSet[anim.mood], anim.mood, anim.moodTick)
    anim.heroImage = portrait !== undefined
    if (portrait !== undefined) anim.shownPng = portrait
    const fitsPortrait = statusLayout(width, true).hasPortrait
    if (portrait !== undefined && canDrawImage === undefined && fitsPortrait) probeImage($, portrait)
    // A boss out turns the status panel to a duel; its frames start over with each new moment of the fight, and
    // only a foe on screen animates.
    const fightFx = liveFx(await read($, bossFx), now)
    const foe = shownBoss(bossNow, fightFx)
    const duel = foe === undefined ? undefined : panelDuel(width, true)
    // Pets out in the background join the fight; one just back throws a shot, its moment ending in a redraw.
    const fighters = petList
      .filter(pet => pet.isBackground === true && (pet.status === 'run' || (pet.status === 'ok' && pet.endedAt !== undefined && now - pet.endedAt < ASSIST_MS)))
      .slice(0, MAX_ALLIES)
    const returning = fighters.reduce<number | undefined>(
      (best, pet, at) => (pet.status === 'ok' && (best === undefined || (pet.endedAt ?? 0) > (fighters[best]?.endedAt ?? 0)) ? at : best),
      undefined,
    )
    const party = {
      allies: fighters.map(pet => petArt(petSeed(pet))),
      ...(returning === undefined || fightFx !== undefined ? {} : { assist: returning }),
      key: `${fighters.map(pet => pet.id).join(',')}@${returning === undefined ? '' : fighters[returning]?.endedAt}`,
    }
    if (party.assist !== undefined) {
      const left = ASSIST_MS - (now - (fighters[party.assist]?.endedAt ?? now))
      assistRedraw?.cancel()
      assistRedraw = $.clock.after(Math.max(0, left), () => $.ui.invalidate('ui.render'))
    }
    if (foe !== undefined && duel !== undefined && duel.scale > 0 && Raster !== undefined) {
      const { scale, arenaColumns } = duel
      const rage = fightFx?.event !== 'defeat' && isEnraged(foe)
      const key = `${foe.kind}:${fightFx?.event ?? 'idle'}:${fightFx?.at ?? 0}:${scale}:${arenaColumns}:${rage}:${party.key}`
      if (anim.boss?.key !== key) {
        const played = bossCells(foe.kind, fightFx?.event, scale, fightFx?.event === 'hit' ? fightFx.damage : 0, arenaColumns, rage, party)
        anim.boss = { key, ...played, columns: arenaColumns, rows: BOSS_ROWS * scale, start: anim.tick, shown: played.frames[0] ?? '' }
      }
    } else {
      anim.boss = undefined
    }
    // A combo of ten or more burns as an aura beside the portrait.
    const comboNow = await read($, combo)
    const tier = auraTier(comboNow.current)
    let aura: { node: RenderChildren; tier: 1 | 2 } | undefined
    if (tier > 0 && !isDown && foe === undefined) {
      const frames = auraFrames(tier as 1 | 2, HERO_CELLS.rows)
      if (Raster !== undefined) {
        const cells = frames.map(composeColors)
        if (anim.aura?.frames[0] !== cells[0]) anim.aura = { frames: cells, shown: cells[0] ?? '' }
        aura = { tier: tier as 1 | 2, node: <Raster key="aura" columns={AURA_COLUMNS} rows={HERO_CELLS.rows} cells={anim.aura?.shown ?? ''} /> }
      } else if (Svg !== undefined) {
        const toHex = (color: number | undefined) => (color === undefined ? undefined : `#${color.toString(16).padStart(6, '0')}`)
        const sprite = spriteSvg(frames.map(frame => frame.map(row => row.map(toHex))), SPRITE_PX, FRAME_MS)
        aura = { tier: tier as 1 | 2, node: <Svg key="aura" source={sprite.source} alt="combo aura" width={sprite.width} height={sprite.height} isInteractive /> }
      }
    } else {
      anim.aura = undefined
    }
    const status = renderStatus(
      ui,
      {
        ...(aura === undefined ? {} : { aura }),
        ...(foe === undefined
          ? {}
          : {
              foe: {
                boss: foe,
                party,
                ...(fightFx === undefined ? {} : { fx: fightFx }),
                ...(Raster === undefined ? {} : { Raster, cells: anim.boss?.shown ?? '' }),
              },
            }),
        hero,
        list: sinceRevive(callList, lastRevive),
        casts: await read($, castCount),
        ...(isDown ? { knockout: 'down' as const } : isRevived ? { knockout: 'revived' as const } : {}),
        ...(rest !== null && now - rest.at < REST_MS ? { rest: { elapsed: now - rest.at, ...(rest.from === undefined ? {} : { from: rest.from }) } } : {}),
        vitals: await read($, vitals),
        combo: comboNow,
        boss: bossNow,
        jobsOut: (await read($, jobs)).filter(job => job.status === 'run').length,
        petsOut: petList.filter(pet => pet.status === 'run').length,
        ...campOf(await read($, outposts)),
        isFlashing: (await read($, flashUntil)) > now,
        width,
        ...(waiting === null ? {} : { waitingFor: waiting }),
        onHelp: () => {
          void update($, isHelpOpen, open => !open)
          void update($, offsets, all => ({ ...all, help: 0 }))
        },
        ...(bossNow === null
          ? {}
          : {
              onFight: () => fillPrompt($, fightText(bossNow), `Ask Claude: ${fightText(bossNow)}`),
            }),
      },
      portrait === undefined && downCells === undefined ? Raster : undefined,
      downCells !== undefined
        ? Raster !== undefined
          ? <Raster key="hero-ko" {...HERO_CELLS} cells={downCells} />
          : Svg === undefined
          ? undefined
          : (() => {
              const sprite = spriteSvg([cellsToPixels(downCells, HERO_CELLS.columns, HERO_CELLS.rows)], SPRITE_PX, FRAME_MS)
              return <Svg key="hero" source={sprite.source} alt={`${hero.title}, knocked out`} width={sprite.width} height={sprite.height} />
            })()
        : portrait !== undefined
        ? (() => {
            const { Image } = $.ui.resolve(e) as ElementTable<'terminal'>
            return <Image key="hero" source={{ png: portrait }} columns={HERO_CELLS.columns} rows={HERO_CELLS.rows} alt={hero.title} />
          })()
        : Svg === undefined
        ? undefined
        : (() => {
            const hurtLeft = anim.hurtUntil - now
            const mood = pickMood(anim.running, hurtLeft)
            hurtRedraw?.cancel()
            hurtRedraw = hurtLeft > 0 ? $.clock.after(hurtLeft, () => $.ui.invalidate('ui.render')) : undefined
            const sprite = heroSprite(hero.id, mood)
            return <Svg key="hero" source={sprite.source} alt={`${hero.title}, ${mood}`} width={sprite.width} height={sprite.height} isInteractive />
          })(),
    )
    // A picture animates by blits too, once the terminal is known to draw it.
    if (anim.heroImage) anim.hasHero = canDrawImage === true && fitsPortrait

    // The icon menu when the slots and the window both have room; one line of labels otherwise.
    const isTerminal = e.surface === 'terminal'
    const sectionGap = isTerminal ? 0 : SECTION_GAP
    const cardGap = isTerminal ? 0 : CARD_GAP
    const card = cardWidth(width - cardGap * (MENU.length - 1), MENU.length, isTerminal ? ICON_COLUMNS : DRAWN_ICON_COLUMNS)
    const roomRows = e.props.scroll.bodyRows - STATUS_ROWS - WINDOW_CHROME_ROWS - sectionGap * 2
    const slotRows = isTerminal ? TAB_ROWS : DRAWN_SLOT_ROWS
    const isIconMenu = card >= (isTerminal ? MIN_SLOT_COLUMNS : DRAWN_MIN_SLOT_COLUMNS) && roomRows - slotRows >= MIN_WINDOW_ROWS
    const menuRows = isIconMenu ? slotRows : 1
    // The tabs sit on the window with no gap between, so their gap is the window's.
    const rows = Math.max(MIN_WINDOW_ROWS, roomRows - menuRows + (isIconMenu ? sectionGap : 0))

    // No label shows a number key: a desktop's button would badge it. On the terminal the number keys are the tab
    // Client's, once a click has given it the keys.
    const pickTab = (id: Tab) => {
      void update($, tab, () => id)
      void update($, isHelpOpen, () => false)
    }
    // On the terminal plain buttons, the name alone; elsewhere the surface's own buttons, the active one primary
    // in the one-line menu; on a card the frame marks it.
    const labelButton = (slot: (typeof MENU)[number], index: number) => {
      const isActive = slot.id === active
      return (
        <Button
          key={`menu-${slot.id}`}
          label={slot.label.toUpperCase()}
          {...(isTerminal ? { plain: true as const } : isIconMenu ? {} : { variant: isActive ? ('primary' as const) : ('secondary' as const) })}
          dimColor={!isActive}
          {...(isActive ? {} : { hover: { scope: `card-${slot.id}`, color: slot.color } })}
          onPress={() => pickTab(slot.id)}
        />
      )
    }

    // On the terminal the menu is a row of folder tabs over the window: each tab its icon over its name, drawn by a
    // Client so a click anywhere on it picks the tab; the selected one framed in its colour, its frame open into
    // the window below, whose top line the window draws around it; the others bare and dim, lit in their colour
    // while hovered. A terminal found to draw pictures shows the icons' full pixel art instead, its price the
    // Client's click and hover: the name under it is a button.
    // Elsewhere a tab bar of the surface's own: the selected tab on a backdrop of its colour's deep shade, its icon
    // in colour and a bar of its colour under it, right on the window's frame of that colour; the others bare, their
    // icons grey and names dim, the name lit in the tab's colour while hovered. The drawn icon takes no click, so a
    // Client over the whole tab does, and the name is plain text as the terminal's is, no button chrome; a surface
    // without the Client keeps the name a button. Too narrow or short for icons, one row of the buttons alone.
    let menu
    // The selected tab's span along the window's top, for the window to leave open.
    let openTab: { left: number; width: number } | undefined
    if (isIconMenu && isTerminal) {
      const Client = $.ui.resolve(e).Client
      const iconPngs = canDrawImage === true ? await menuIconPngs($) : undefined
      const Image = iconPngs === undefined ? undefined : ($.ui.resolve(e) as ElementTable<'terminal'>).Image
      const ids = MENU.map(slot => slot.id)
      // Inside the selected tab's frame.
      const inside = Math.max(0, card - 2)
      const faceRows = ICON_ROWS + 1
      // The tabs spread from edge to edge, the spare columns shared between them.
      const spare = Math.max(0, width - card * MENU.length)
      const lefts = MENU.map((_, index) => index * card + Math.floor((spare * index) / Math.max(1, MENU.length - 1)))
      const activeIndex = Math.max(0, MENU.findIndex(slot => slot.id === active))
      openTab = { left: lefts[activeIndex]!, width: card }
      const face = (slot: (typeof MENU)[number], index: number, isActive: boolean) => {
        if (Image && iconPngs) {
          return (
            <Box key={`icon-box-${slot.id}`} flexDirection="column" width={inside} height={faceRows} alignItems="center">
              <Image
                key={`icon-${slot.id}`}
                source={{ png: iconPngs.get(slot.id)![isActive ? 0 : 1] }}
                columns={Math.min(PICTURE_COLUMNS, inside)}
                rows={ICON_ROWS}
                alt={slot.label}
              />
              {labelButton(slot, index)}
            </Box>
          )
        }
        const iconProps = {
          id: slot.id,
          ids,
          active,
          isHelpOpen: helpOpen,
          icon: iconText(slot, true),
          dimIcon: iconText(slot, false),
          label: slot.label.toUpperCase(),
          color: slot.color,
          width: inside,
          scope: `card-${slot.id}`,
        } satisfies MenuIconProps
        return <Client key={`icon-${slot.id}`} module="./menu-client.tsx" props={iconProps} width={inside} height={faceRows} />
      }
      const side = (slot: (typeof MENU)[number]) => frameSide(ui, slot.color, faceRows)
      menu = (
        <Box flexDirection="row" width={width} height={menuRows}>
          {MENU.map((slot, index) => {
            const isActive = slot.id === active
            const gap = lefts[index]! - (index === 0 ? 0 : lefts[index - 1]! + card)
            return (
              <Box key={`card-${slot.id}`} flexDirection="column" width={card} height={menuRows} marginLeft={gap}>
                {isActive ? (
                  <>
                    <Text color={slot.color}>{`╭${'─'.repeat(inside)}╮`}</Text>
                    <Box flexDirection="row" height={faceRows}>
                      {side(slot)}
                      {face(slot, index, true)}
                      {side(slot)}
                    </Box>
                  </>
                ) : (
                  <>
                    <Box height={1} />
                    <Box flexDirection="row" height={faceRows} paddingX={1}>
                      {face(slot, index, false)}
                    </Box>
                  </>
                )}
              </Box>
            )
          })}
        </Box>
      )
    } else if (isIconMenu) {
      // A Client laid over each tab takes a click anywhere on it, the drawing and the name alike, and the number
      // and arrow keys once it has them. The bar lies along the tab's foot, out of the flow, so the icon and the
      // name centre in the whole tab.
      const Client = (ui as ElementTable<'desktop'>).Client as ElementTable<'desktop'>['Client'] | undefined
      const ids = MENU.map(slot => slot.id)
      menu = (
        <Box flexDirection="row" width={width} height={menuRows} justifyContent="space-between" columnGap={cardGap}>
          {MENU.map((slot, index) => {
            const isActive = slot.id === active
            const { art, palette } = drawnIcon(slot, isActive)
            const icon = spriteSvg([gridToPixels(art, palette)], DRAWN_ICON_PX, 0)
            return (
              <Box
                key={`card-${slot.id}`}
                flexDirection="column"
                alignItems="center"
                justifyContent="center"
                width={card}
                height={menuRows}
                {...(isActive ? { backgroundColor: tintOf(slot.color, 0.22) } : {})}
              >
                {Svg && (
                  <Box key={`art-${slot.id}`} height={DRAWN_ICON_ROWS} alignItems="center" justifyContent="center">
                    <Svg source={icon.source} alt={slot.label} width={icon.width} height={icon.height} />
                  </Box>
                )}
                <Box flexDirection="row" width={card} height={1} justifyContent="center">
                  {Client ? (
                    <Text
                      key={`menu-label-${slot.id}`}
                      bold={isActive}
                      {...(isActive ? { color: slot.color } : { dimColor: true, hover: { scope: `card-${slot.id}`, color: slot.color, dimColor: false } })}
                    >
                      {slot.label.toUpperCase()}
                    </Text>
                  ) : (
                    labelButton(slot, index)
                  )}
                </Box>
                <Box key={`line-${slot.id}`} position="absolute" bottom={0} left={0} width={card} height={1} alignItems="flex-end">
                  {isActive && Svg && (
                    <Svg source={tabLineSvg(card, slot.color)} alt={`${slot.label} selected`} width={card * COLUMN_PX} height={TAB_LINE_HEIGHT} />
                  )}
                </Box>
                {Client && (
                  <Box key={`hit-${slot.id}`} position="absolute" top={0} left={0} width={card} height={menuRows}>
                    <Client
                      key={`icon-${slot.id}`}
                      module="./menu-client.tsx"
                      props={{
                        id: slot.id,
                        ids,
                        active,
                        isHelpOpen: helpOpen,
                        icon: [],
                        dimIcon: [],
                        label: slot.label,
                        color: slot.color,
                        width: card,
                        scope: `card-${slot.id}`,
                        overlay: { height: menuRows },
                      } satisfies MenuIconProps}
                      width={card}
                      height={menuRows}
                    />
                  </Box>
                )}
              </Box>
            )
          })}
        </Box>
      )
    } else {
      // The terminal's labels close up as the pane narrows, so the last ones stay on screen.
      const labelColumns = MENU.reduce((sum, slot) => sum + slot.label.length, 0)
      const labelGap = isTerminal ? Math.max(0, Math.min(2, Math.floor((width - labelColumns) / (MENU.length - 1)))) : 2
      menu = (
        <Box key="menu-labels" flexDirection="row" columnGap={labelGap} height={1} width={width}>
          {MENU.map((slot, index) => labelButton(slot, index))}
        </Box>
      )
    }

    const inner = Math.max(0, width - WINDOW_CHROME_COLUMNS)
    const view = active === 'map' ? await read($, mapView) : { view: 'map' as const }
    const tabKey = (active === 'map' && view.view !== 'map' ? `map:${view.view}` : active) as PageKey
    const windowKey: PageKey = helpOpen ? 'help' : tabKey
    const offset = (await read($, offsets))[windowKey] ?? 0
    const page = await pageFor($, windowKey, { ui, view, inner, now, Raster, isTerminal: e.surface === 'terminal', callList, petList, progress: progressNow, offset, rows })
    const items = page.items ?? []
    // A list scrolls a row a step; items an item a step, where the stops between them are.
    layout = { rows, total: page.list?.rows.length ?? totalRows(items), key: windowKey, ...(page.list === undefined ? { stops: itemStops(items) } : {}) }
    const body = page.list === undefined ? undefined : pickBody($, e, page.list, offset, rows, inner)

    if (active === 'pets') {
      // Only the pets the window shows can take a blit.
      const shown = new Set(pageItems(items, offset, rows).shown.map(item => `pet-${item.key}`))
      for (const key of anim.pets.keys()) if (!shown.has(key)) anim.pets.delete(key)
    }
    // Only an overworld the window shows (the map itself, not its bag) can take a blit.
    if (windowKey !== 'map' || !pageItems(items, offset, rows).shown.some(item => item.key === 'overworld')) anim.overworld = undefined
    if (active === 'jobs') {
      // Only the jobs the window shows can take a blit.
      const shown = new Set(pageItems(items, offset, rows).shown.map(item => `job-${item.key}`))
      for (const key of anim.jobs.keys()) if (!shown.has(key)) anim.jobs.delete(key)
    }
    if (
      anim.hasHero ||
      (active === 'pets' && anim.pets.size > 0) ||
      anim.overworld !== undefined ||
      anim.boss !== undefined ||
      anim.aura !== undefined ||
      (active === 'jobs' && anim.jobs.size > 0)
    ) {
      startAnim($)
    }

    // The tabs sit right on the window, the selected one's frame meeting its frame.
    return (
      <Box flexDirection="column" width={width} rowGap={sectionGap}>
        {status}
        <Box flexDirection="column" width={width} rowGap={isIconMenu ? 0 : sectionGap}>
          {menu}
          {renderWindow(ui, {
          title: page.title ?? entry.title,
          subtitle: page.subtitle,
          color: entry.color,
          items,
          offset,
          rows,
          width,
          ...(body === undefined ? {} : { body }),
          ...(page.actions === undefined ? {} : { actions: page.actions }),
          scroll: {
            up: () => void scrollWindow($, layout, -1),
            down: () => void scrollWindow($, layout, 1),
          },
          ...(Svg === undefined ? {} : { Svg }),
          ...(openTab === undefined ? {} : { tab: openTab }),
          })}
        </Box>
      </Box>
    )
  })
}

