import type { ElementTable } from 'claude-code'

import type { Pet } from '../types'
import { FRAME_MS, PET_TICKS, anim } from './anim'
import { PET_COLUMNS, PET_ROWS, petCells, petSeed, speciesFor } from './pet-sprites'
import { formatElapsed, oneLine } from './util'
import { cellsToPixels, spriteSvg } from './svg'
import type { Item } from './window'

// Three text rows beside the sprite, then a blank row.
const CARD_ROWS = 4
const SPRITE_GAP = 1
// CSS pixels per sprite pixel where the sprite is a drawing: eight columns at about eight pixels each.
const PET_PX = 8

// A running pet hops between its two frames; one back or fainted holds the first.
const petSprite = (seed: string, status: Pet['status']) => {
  const frames = status === 'run' ? [0, 1] : [0]
  return spriteSvg(
    frames.map(frame => cellsToPixels(petCells(seed, status, frame), PET_COLUMNS, PET_ROWS)),
    PET_PX,
    FRAME_MS * PET_TICKS,
  )
}

// Pets still out first, then the ones back, each newest first.
export const rosterOrder = (list: readonly Pet[]): Pet[] => {
  const newestFirst = list.slice().reverse()
  return [...newestFirst.filter(pet => pet.status === 'run'), ...newestFirst.filter(pet => pet.status !== 'run')]
}

const statusLine = (pet: Pet, now: number) => {
  const elapsed = formatElapsed((pet.endedAt ?? now) - pet.startedAt)
  if (pet.status === 'run') return { text: `✦ questing ${elapsed}`, color: 'yellow' }
  if (pet.status === 'ok') return { text: `✓ returned ${elapsed}`, color: 'green' }
  return { text: `✗ fainted ${elapsed}`, color: 'red' }
}

export const partySubtitle = (list: readonly Pet[]): string =>
  `${list.filter(pet => pet.status === 'run').length} questing · ${list.length} summoned`

export function petItems(
  ui: ElementTable,
  list: readonly Pet[],
  now: number,
  width: number,
  Raster?: ElementTable<'terminal'>['Raster'],
): Item[] {
  const { Box, Text } = ui
  // The animation repaints the running pets; the window decides which are on screen, so all are candidates.
  anim.pets = new Map(
    list
      .filter(pet => pet.status === 'run')
      .map(pet => [`pet-${pet.id}`, { seed: petSeed(pet), shown: anim.pets.get(`pet-${pet.id}`)?.shown ?? '' }]),
  )
  if (list.length === 0) {
    return [{ key: 'empty', rows: 1, node: <Text dimColor>No companions yet. Subagents you summon join the party.</Text> }]
  }
  const Svg = Raster === undefined && 'Svg' in ui ? ui.Svg : undefined
  const textWidth = Math.max(0, width - (Raster || Svg ? PET_COLUMNS + SPRITE_GAP : 0))
  return rosterOrder(list).map(pet => {
    const seed = petSeed(pet)
    const species = speciesFor(seed)
    const status = statusLine(pet, now)
    const detail =
      pet.status === 'run'
        ? `⚔ ${pet.actions} · ${pet.lastTool ?? 'setting out'} ${pet.lastSummary ?? ''}`
        : `↩ ${pet.loot ?? `${pet.actions} actions`}`
    return {
      key: pet.id,
      rows: CARD_ROWS,
      node: (
        <Box flexDirection="row" height={CARD_ROWS}>
          {Raster && (
            <Box width={PET_COLUMNS + SPRITE_GAP}>
              <Raster key={`pet-${pet.id}`} columns={PET_COLUMNS} rows={PET_ROWS} cells={petCells(seed, pet.status, 0)} />
            </Box>
          )}
          {Svg &&
            (() => {
              const sprite = petSprite(seed, pet.status)
              return (
                <Box width={PET_COLUMNS + SPRITE_GAP}>
                  <Svg key={`pet-${pet.id}`} source={sprite.source} alt={species.name} width={sprite.width} height={sprite.height} {...(sprite.isAnimated ? { isInteractive: true } : {})} />
                </Box>
              )
            })()}
          <Box flexDirection="column" width={textWidth}>
            <Box height={1}>
              <Box flexGrow={1}>
                <Text wrap="truncate">
                  {/* White fades on a light terminal; the default foreground reads on either (as in the bag). */}
                  <Text bold color={pet.status === 'err' ? 'gray' : species.color === 'white' ? undefined : species.color}>
                    {species.name}
                  </Text>
                  <Text dimColor> {oneLine(pet.kind, 16)}</Text>
                  {pet.camp !== undefined && <Text color="cyan"> ⚑{pet.camp}</Text>}
                </Text>
              </Box>
              <Text color={status.color}>{status.text}</Text>
            </Box>
            <Text wrap="truncate">{oneLine(pet.description, textWidth)}</Text>
            <Text dimColor wrap="truncate">
              {oneLine(detail, textWidth)}
            </Text>
          </Box>
        </Box>
      ),
    }
  })
}

